import {test,expect} from "bun:test";
import {createHash} from "node:crypto";
import {createReliability,protocolVersion} from "./reliability";
import {canonical,sha256} from "./canonical";
import {handleWriteCreateRequest} from "./write-create";
import {handleWriteModifyRequest} from "./write-modify";
import {handleWriteComponentRequest} from "./write-components";
import {handleWriteHtmlRequest} from "./write-html";

function fixture(storage = new Map<string,any>()) {
  const root:any={id:"0:0",type:"DOCUMENT",name:"Fixture",children:[]};
  const page:any={id:"0:1",type:"PAGE",name:"Page",parent:root,children:[],loadAsync:async()=>{}};root.children=[page];
  let sequence=1, dispatches=0;
  const nodes=new Map<string,any>([[root.id,root],[page.id,page]]);
  const api:any={root,currentPage:page,fileKey:"non-sensitive-test-file",editorType:"figma",getNodeByIdAsync:async(id:string)=>nodes.get(id)??null,commitUndo(){},clientStorage:{async getAsync(k:string){return storage.get(k)},async setAsync(k:string,v:any){storage.set(k,structuredClone(v))}}};
  page.appendChild=(node:any)=>{if(node.parent?.children)node.parent.children=node.parent.children.filter((n:any)=>n!==node);page.children.push(node);node.parent=page;};
  function node(type="FRAME") {
    const n:any={id:`1:${sequence++}`,type,name:"Fixture",x:0,y:0,width:100,height:100,visible:true,children:[],reactions:[],fills:[],resize(w:number,h:number){this.width=w;this.height=h},remove(){this.parent.children=this.parent.children.filter((n:any)=>n!==this);nodes.delete(this.id)}};
    n.appendChild=(c:any)=>{if(c.parent?.children)c.parent.children=c.parent.children.filter((n:any)=>n!==c);n.children.push(c);c.parent=n};
    n.clone=()=>{const c=node(n.type);c.name=n.name;return c};
    nodes.set(n.id,n);page.appendChild(n);return n;
  }
  api.createFrame=()=>node();
  const reliability=createReliability(api);
  const dispatch=async(r:any)=>{dispatches++;(globalThis as any).figma=api;return (await handleWriteCreateRequest(r))??(await handleWriteModifyRequest(r))??(await handleWriteComponentRequest(r));};
  const request=(type:string,params:any={},ids:string[]=[])=>({type,protocolVersion,requestId:"transport-ignored",nodeIds:ids,params});
  const run=(type:string,params:any={},ids:string[]=[],handler=dispatch)=>reliability.handle(request(type,params,ids),handler);
  const lookup=(operationId:string)=>run("get_operation_receipt",{operationId});
  return {api,node,page,nodes,storage,reliability,dispatch,run,request,lookup,count:()=>dispatches};
}
const id=(n:number)=>`operation-fixture-${String(n).padStart(8,"0")}`;
test("canonical SHA-256 matches Node across Unicode, arrays and key order",()=>{
  for(const v of [null,{z:2,a:"☕你好🌍"},[1,0.1,true],"", "a".repeat(1000)])expect(sha256(canonical(v))).toBe(createHash("sha256").update(canonical(v)).digest("hex"));
  expect(canonical({b:1,a:2})).toBe('{"a":2,"b":1}');
});
test("new actual native create is committed with IDs and before/after revisions",async()=>{
  const f=fixture(),r=await f.run("create_frame",{operationId:id(1),name:"A"});
  expect(r.data.operation.state).toBe("COMMITTED");expect(r.data.operation.createdNodeIds).toEqual([r.data.id]);expect(r.data.operation.revisionBefore).not.toBe(r.data.operation.revisionAfter);
});
test("duplicate actual create returns same ID and never dispatches twice",async()=>{
 const f=fixture(),p={operationId:id(2),name:"A"};const a=await f.run("create_frame",p),b=await f.run("create_frame",p);
 expect(a.data.id).toBe(b.data.id);expect(b.data.operation.replayed).toBe(true);expect(f.page.children.length).toBe(1);expect(f.count()).toBe(1);
});
