test("partial HTML batch failure is never committed or replayed",async()=>{
 const f=fixture(),req=f.request("write_html_batch",{operationId:id(8),slides:[{html:"<div/>"}]});let calls=0;
 const handler=async()=>{calls++;f.node();throw Error("font failed /private/secret")};
 const r=await f.reliability.handle(req,handler);expect(r.data.operation.state).toBe("FAILED_AFTER_PARTIAL_WRITE");expect(r.data.operation.createdNodeIds.length).toBe(1);
 await f.reliability.handle(req,handler);expect(calls).toBe(1);expect(JSON.stringify((await f.lookup(id(8))).data)).not.toContain("secret");
});
